// verify-ward-scope.cjs — ward-scoped access (openspec/changes/paediatric-wards, task 2.1;
// specs/ward-scoped-access, design D2).
//
// Pp, 2026-11-24 ("ทำก่อน"): a doctor, nurse or admin reads and writes only the infants of the wards
// their account holds, and the server enforces it. Until now every signed-in role but pharmacy got
// every ward's infants. The real gas-backend.gs runs in gas-vm-sandbox.cjs, with a fixture ward PED
// (four beds) planted in data.js WARDS and the backend copy regenerated by tools/ward-table.cjs, as
// REFERENCE.md § Adding a ward says. Made-up infants only.
//
//   § 1  the sync: each account gets its own wards' infants and nothing of the others; `wards`
//   § 2  the copy the sign-in reply embeds, and an account with no ward
//   § 3  two wards syncing in turn, with no write between (the cached reply)
//   § 4  a registration that matches another ward's infant: no name, bed or ID
//   § 5  a bed taken by another ward's infant: no name; a transfer out of the caller's ward
//   § 6  every write and the order lock, refused outside the caller's wards, before any sheet
//        changes, naming no one, audited without a patient identifier
//   § 7  a parked child; a bed in no ward; no bed at all
//   § 8  a registry read that fails: refused, not let through
//   § 9  the TPN room still lists every ward's orders; pharmacy still reads no registry
//   § 10 setStaffWards and getStaffWards: admin only, audited, checked
//   § 11 the migration: fills doctors and nurses with NICU,SCN, idempotent, lists infants with no
//        ward, and every account sees the same infants before and after
//
// NEGATIVE CONTROL — red against main before ward scope (c37d8b6):
//   git -C <repo> archive c37d8b6 | tar -x -C /tmp/main-c37d8b6
//   NEOFEED_TREE=/tmp/main-c37d8b6 node test/verify-ward-scope.cjs
process.env.TZ = process.env.TZ || 'Asia/Bangkok';
const fs = require('fs');
const os = require('os');
const path = require('path');
const { boot, recorder, withNow, wardToday, addDays } = require('./gas-vm-sandbox.cjs');

const TREE = path.resolve(process.env.NEOFEED_TREE || path.join(__dirname, '..'));
const read = (f) => fs.readFileSync(path.join(TREE, f), 'utf8');
const T = recorder('WARD-SCOPED ACCESS');

// ── The fixture ward, planted the way REFERENCE.md § Adding a ward plants one ──
const PED_ROW = '{ key: "PED", label: "PED", sub: "PED 1–4", stickerLabel: "PED(test)", beds: [{ prefix: "PED", count: 4 }] },';
const WT = require(path.join(TREE, 'tools', 'ward-table.cjs'));
const planted = WT.write({ 'data.js': WT.plantWard(read('data.js'), PED_ROW),
  'gas-backend.gs': read('gas-backend.gs'), 'tpn-room-core.js': read('tpn-room-core.js') });
const SRC = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'nf-ward-scope-')), 'gas-backend.gs');
fs.writeFileSync(SRC, planted['gas-backend.gs']);

const TODAY = wardToday();
const NOON = Date.parse(TODAY + 'T05:00:00Z');
const hop = (bed) => ({ bed, date: addDays(TODAY, -1), at: addDays(TODAY, -1) + 'T03:00:00.000Z' });

// One infant per case. A name and an ID no other infant's contain, so a reply can be searched for
// either. Every one is on the unit and inside the sync window.
const INFANTS = [
  { sid: 'NF-310001', bed: 'NICU 3', ward: 'NICU' },
  { sid: 'NF-310002', bed: 'SCN 5', ward: 'SCN' },
  { sid: 'NF-310003', bed: 'PED 2', ward: 'PED' },
  { sid: 'NF-310004', bed: '', hops: [hop('PED 1')], ward: 'PED' },          // parked, left PED 1
  { sid: 'NF-310005', bed: '', hops: [hop('NICU 9')], ward: 'NICU' },        // parked, left NICU 9
  { sid: 'NF-310006', bed: 'OR 1', ward: null },                              // a bed in no ward
  { sid: 'NF-310007', bed: '', ward: null },                                  // no bed, never had one
];
const NAME = (sid) => 'NAME' + sid.slice(-4);   // "NAME0001"
const idsOf = (ward) => INFANTS.filter(i => i.ward === ward).map(i => i.sid);
const ALL_IDS = INFANTS.map(i => i.sid);
const BW = { 'NF-310003': 2345 };
const DOB = addDays(TODAY, -40);

const ACCOUNTS = {
  admin: { email: 'admin@kcmh.test', role: 'admin', wards: '' },
  nicuDoc: { email: 'nicu.doc@kcmh.test', role: 'doctor', wards: 'NICU,SCN' },
  nicuNurse: { email: 'nicu.nurse@kcmh.test', role: 'nurse', wards: 'NICU,SCN' },
  pedDoc: { email: 'ped.doc@kcmh.test', role: 'doctor', wards: 'PED' },
  pedNurse: { email: 'ped.nurse@kcmh.test', role: 'nurse', wards: 'PED' },
  noWard: { email: 'new.doc@kcmh.test', role: 'doctor', wards: '' },
  rx: { email: 'rx@kcmh.test', role: 'pharmacy', wards: '' },
};
const PWD = 'Ward-Scope-Password-1';

function ward(opts) {
  opts = opts || {};
  const g = boot({ src: SRC });
  for (const [k, a] of Object.entries(ACCOUNTS)) g.addStaff(a.email, a.role, PWD, { name: 'Staff ' + k, wards: a.wards });
  g.tok = {};
  for (const [k, a] of Object.entries(ACCOUNTS)) g.tok[k] = g.session(a.email, a.role);
  g.as = (who, body) => g.post(Object.assign({ token: g.tok[who] }, body));
  g.asText = (who, body) => g.postText(Object.assign({ token: g.tok[who] }, body));
  for (const i of INFANTS) {
    g.seedPatient({ sessionId: i.sid, name: NAME(i.sid), initials: 'นน', bw: BW[i.sid] || 1500 + Number(i.sid.slice(-1)), ga: 32.1,
      sex: 'boys', dob: DOB, admissionDate: DOB, status: 'Active', currentBed: i.bed, diagnosis: 'RDS',
      weights: [{ dol: 1, w: 1500 }], bedHistory: i.hops || [] });
    if (!opts.noLog) g.sheet('Daily_Log').appendRow(g.logRow(i.sid, addDays(TODAY, -1)));
  }
  if (opts.nursing) g.props.set('NURSING_LOG_ENABLED', 'true');
  return g;
}
const sync = (g, who) => g.as(who, { action: 'getActivePatients' });
const sids = (reply) => (reply && Array.isArray(reply.patients) ? reply.patients.map(p => p.sessionId).sort() : reply);
// What of `others` a reply names: any of their IDs or names, anywhere in its text.
const leaks = (text, others) => others.filter(sid => text.includes(sid) || text.includes(NAME(sid)));
const sheetsNow = (g) => JSON.stringify(['Patient_Registry', 'Daily_Log', 'Nursing_Log', 'Staff']
  .map(n => g.sheet(n) ? g.sheet(n).data : null));

// ── An order the backend accepts (verify-pharmacy-backend-1030.cjs's, dated today) ──
const PJ = (date) => ({ v: 1, constantsVersion: '2026-11-18.1', orderDate: date, dol: '10',
  dosingWeightKg: '1.6', factor: '1.9', deliveredMl: '160', deadMl: '30', preparedMl: '190',
  stockMl: { d50w: '38', aminoven10: '38', amiparen10: '0', aminoplasmal15: '0', nacl20: '1.1', glycophos: '0',
    k2hpo4: '0', naAcetate: '0', kcl: '2.4', mgso4_10: '0.9', caGluconate: '0', soluvit: '1.9', peditrace: '1.9',
    heparin: '1.9', wfi: '103.9', znso4: '0', addamel: '0' },
  delivered: { dextrosePct: '10', dextroseG: '16', aminoAcidPct: '2',
    aminoAcidG: { aminoven10: '3.2', amiparen10: '0', aminoplasmal15: '0' },
    naMeq: '3.2', kMeq: '4', caMg: '0', mgMg: '7.8', phosphateMg: '0', acetateMeq: '0', clMeq: '7.2', znMg: '0.4',
    soluvitMl: '1.6', peditraceMl: '1.6', addamelMl: '0', heparinUnits: '160', osmolarity: '794', kcal: '67' },
  critical: null });
const ORDER = (status) => ({ ts: TODAY, dol: 10, weight: 1600, fluid: 150, gir: 7, pro: 2, kcal: 42, na: 2, k: 2.5, ca: 0, p: 0,
  enVolPerKg: 0, route: 'TPN central', status: status || 'submitted', constantsVersion: '2026-11-18.1', printJson: PJ(TODAY),
  calcInput: { wtG: 1600, tpnWtG: 1600, stops: [] } });
const reg = (sid, bed, extra) => Object.assign({ sessionId: sid, name: 'ใหม่ ทดสอบ', initials: 'ใท', bw: 1700, ga: 33.1, sex: 'girls',
  dob: addDays(TODAY, -2), admissionDate: addDays(TODAY, -2), twinSuffix: '', status: 'Active', currentBed: bed,
  diagnosis: 'RDS', weights: [{ dol: 1, w: 1700 }], lengths: [], hcs: [], bedHistory: [], statusDate: '', multiplesCount: 0 }, extra || {});
// The record as this device last received it (the three-way merge's `base`).
const asSynced = (g, who, sid) => (sync(g, who).patients || []).find(p => p.sessionId === sid);

T.section('§1 the sync carries only the caller\'s wards', () => withNow(NOON, () => {
  const g = ward();
  const nicu = [...idsOf('NICU'), ...idsOf('SCN')].sort();
  const ped = idsOf('PED').sort();
  T.eq('1.1 a NICU+SCN doctor: NICU and SCN infants, the parked NICU infant included', sids(sync(g, 'nicuDoc')), nicu);
  T.eq('1.2 a NICU+SCN nurse: the same', sids(sync(g, 'nicuNurse')), nicu);
  T.eq('1.3 a PED doctor: PED infants, the parked PED child included', sids(sync(g, 'pedDoc')), ped);
  T.eq('1.4 a PED nurse: the same', sids(sync(g, 'pedNurse')), ped);
  T.eq('1.5 an admin: every infant, a bed in no ward and no bed included', sids(sync(g, 'admin')), ALL_IDS.slice().sort());
  T.eq('1.6 an account with no ward: no infant', sids(sync(g, 'noWard')), []);
  const pedText = g.asText('pedNurse', { action: 'getActivePatients' });
  const notPed = ALL_IDS.filter(s => !ped.includes(s));
  T.eq('1.7 the PED nurse\'s reply names no NICU, SCN or unwarded infant, in any field', leaks(pedText, notPed), []);
  const pedReply = JSON.parse(pedText);
  T.eq('1.8 …and carries their log rows for PED only', Object.keys(pedReply.log || {}).sort(), ped);
  T.eq('1.9 the reply says which wards it holds', [sync(g, 'nicuDoc').wards, sync(g, 'pedNurse').wards, sync(g, 'noWard').wards],
    [['NICU', 'SCN'], ['PED'], []]);
  T.eq('1.10 an admin\'s reply holds every ward of the table', sync(g, 'admin').wards, ['NICU', 'SCN', 'PED']);
  T.ok('1.11 a ward cell in any case and spacing reads the same (" scn ; nicu ")', (() => {
    const s = g.sheet('Staff').data; const row = s.find(r => r[0] === ACCOUNTS.nicuNurse.email);
    row[8] = ' scn ; nicu '; g.expireStaffCache(ACCOUNTS.nicuNurse.email);
    return JSON.stringify(sids(sync(g, 'nicuNurse'))) === JSON.stringify(nicu);
  })());
  T.ok('1.12 a ward key not in the table gives nothing ("ICU")', (() => {
    const row = g.sheet('Staff').data.find(r => r[0] === ACCOUNTS.nicuNurse.email);
    row[8] = 'ICU'; g.expireStaffCache(ACCOUNTS.nicuNurse.email);
    return JSON.stringify(sids(sync(g, 'nicuNurse'))) === '[]';
  })());
  T.ok('1.13 "*" in a doctor\'s cell is not every ward: only an admin holds every ward', (() => {
    const row = g.sheet('Staff').data.find(r => r[0] === ACCOUNTS.nicuNurse.email);
    row[8] = '*'; g.expireStaffCache(ACCOUNTS.nicuNurse.email);
    return JSON.stringify(sids(sync(g, 'nicuNurse'))) === '[]';
  })());
  T.ok('1.14 an admin\'s archive read still reaches every infant', sids(g.as('admin', { action: 'getActivePatients', includeArchived: true })).length === ALL_IDS.length);
  T.eq('1.15 a doctor asking for the archive gets only the ward list', sids(g.as('pedDoc', { action: 'getActivePatients', includeArchived: true })), ped);
}));

T.section('§2 the sign-in reply\'s copy, and an account with no ward', () => withNow(NOON, () => {
  const g = ward();
  const login = (who) => JSON.parse(g.postText({ action: 'login', email: ACCOUNTS[who].email, password: PWD, wantSync: true }));
  const ped = login('pedNurse');
  T.ok('2.1 a PED nurse signs in', ped.status === 'ok', ped);
  T.eq('2.2 the reply\'s copy holds PED infants only', sids(ped.sync), idsOf('PED').sort());
  T.eq('2.3 …and no field of any other infant', leaks(JSON.stringify(ped), ALL_IDS.filter(s => !idsOf('PED').includes(s))), []);
  T.eq('2.4 …and says its wards', ped.sync && ped.sync.wards, ['PED']);
  const none = login('noWard');
  T.ok('2.5 an account with no ward signs in', none.status === 'ok' && !!none.token, none);
  T.eq('2.6 …and gets no infant, and an empty ward list', [sids(none.sync), none.sync && none.sync.wards], [[], []]);
  const nicu = login('nicuDoc');
  T.eq('2.7 a NICU+SCN doctor\'s copy: NICU and SCN', sids(nicu.sync), [...idsOf('NICU'), ...idsOf('SCN')].sort());
}));

T.section('§3 two wards sync in turn, no write between', () => withNow(NOON, () => {
  const g = ward();
  const a = sync(g, 'nicuDoc'), b = sync(g, 'pedDoc'), c = sync(g, 'nicuDoc'), d = sync(g, 'pedDoc');
  T.eq('3.1 NICU, then PED, then NICU, then PED: each holds its own', [sids(a), sids(b), sids(c), sids(d)],
    [sids(a), idsOf('PED').sort(), [...idsOf('NICU'), ...idsOf('SCN')].sort(), idsOf('PED').sort()]);
  T.eq('3.2 the first NICU reply was NICU and SCN', sids(a), [...idsOf('NICU'), ...idsOf('SCN')].sort());
  const keys = [...g.cacheStore.keys()].filter(k => /^sync/.test(k) && !/_\d+$/.test(k));
  T.ok('3.3 each ward set is cached under its own key', keys.length >= 2, keys);
  const e = sync(g, 'admin'), f = sync(g, 'noWard'), h = sync(g, 'pedNurse');
  T.eq('3.4 an admin, an account with no ward, then a PED nurse, straight after', [sids(e).length, sids(f), sids(h)],
    [ALL_IDS.length, [], idsOf('PED').sort()]);
  // A write drops every ward's cached reply: the PED doctor's next read sees a NICU-to-PED move.
  const moved = asSynced(g, 'nicuDoc', 'NF-310001');
  const r = g.as('nicuDoc', { action: 'updatePatient', patient: Object.assign({}, moved, { currentBed: 'PED 3' }), base: moved });
  T.ok('3.5 a NICU doctor moves an infant to a free PED bed', r.ok === true, r);
  T.ok('3.6 the PED doctor\'s next sync has the infant', sids(sync(g, 'pedDoc')).includes('NF-310001'));
  T.ok('3.7 the NICU doctor\'s next sync does not', !sids(sync(g, 'nicuDoc')).includes('NF-310001'));
}));

T.section('§4 a registration that matches another ward\'s infant', () => withNow(NOON, () => {
  const g = ward();
  const twin = reg('NF-320001', 'NICU 7', { bw: BW['NF-310003'], dob: DOB, admissionDate: DOB });
  const r = g.as('nicuDoc', { action: 'registerPatient', isNew: true, patient: twin });
  T.ok('4.1 a NICU doctor registering a PED child\'s BW and date of birth is asked first', r.needsConfirm === true && r.code === 'PossibleDuplicate', r);
  T.ok('4.2 …told a matching record is in another ward', /หออื่น/.test(r.error || ''), r.error);
  T.eq('4.3 …and given no name, bed or ID', [leaks(JSON.stringify(r), ['NF-310003']), /PED 2/.test(JSON.stringify(r))], [[], false]);
  const same = g.as('pedDoc', { action: 'registerPatient', isNew: true, patient: reg('NF-320002', 'PED 4', { bw: BW['NF-310003'], dob: DOB, admissionDate: DOB }) });
  T.ok('4.4 the PED doctor is shown the PED record, as before', same.needsConfirm === true && (same.error || '').includes('NF-310003'), same);
  T.ok('4.5 nothing was written', !g.rows('Patient_Registry').some(row => /^NF-32/.test(row[0])));
}));

T.section('§5 a bed taken by another ward\'s infant; a transfer out of the caller\'s ward', () => withNow(NOON, () => {
  const g = ward();
  const n1 = asSynced(g, 'nicuDoc', 'NF-310001');
  const before = sheetsNow(g);
  const r = g.as('nicuDoc', { action: 'updatePatient', patient: Object.assign({}, n1, { currentBed: 'PED 2' }), base: n1 });
  T.ok('5.1 a NICU doctor moving an infant to PED 2, which a PED child holds, is refused', !!r.error && r.ok !== true, r);
  T.ok('5.2 …told the bed is taken', /PED 2/.test(r.error || '') && /อยู่แล้ว|ไม่ว่าง/.test(r.error || ''), r.error);
  T.eq('5.3 …and not who holds it', leaks(JSON.stringify(r), ['NF-310003']), []);
  T.ok('5.4 nothing changed', sheetsNow(g) === before);
  const s1 = asSynced(g, 'nicuDoc', 'NF-310002');
  const own = g.as('nicuDoc', { action: 'updatePatient', patient: Object.assign({}, s1, { currentBed: 'NICU 3' }), base: s1 });
  T.ok('5.5 a bed in the caller\'s own ward still names its holder, as before', (own.error || '').includes(NAME('NF-310001')), own);
  const out = g.as('nicuDoc', { action: 'updatePatient', patient: Object.assign({}, n1, { currentBed: 'PED 4' }), base: n1 });
  T.ok('5.6 a NICU doctor moves an infant to a free PED bed: saved', out.ok === true, out);
  T.ok('5.7 the next NICU sync no longer has the infant; the PED sync does',
    !sids(sync(g, 'nicuDoc')).includes('NF-310001') && sids(sync(g, 'pedDoc')).includes('NF-310001'));
  const back = g.as('nicuDoc', { action: 'updatePatient', patient: Object.assign({}, n1, { currentBed: 'NICU 3' }), base: n1 });
  T.ok('5.8 …and can no longer change the infant', !!back.error && back.ok !== true, back);
}));

// Every action that names a patient, sent by the PED doctor about the NICU infant NF-310001.
function writes(g) {
  const logRow = g.rows('Daily_Log').find(r => r[1] === 'NF-310001');
  const n1 = asSynced(g, 'nicuDoc', 'NF-310001');
  return [
    ['logDailyNutrition', { action: 'logDailyNutrition', sessionId: 'NF-310001', entry: ORDER('draft') }],
    ['updateDailyNutrition', { action: 'updateDailyNutrition', sessionId: 'NF-310001', entryId: logRow[25], expectedLastModified: logRow[26], entry: ORDER('draft') }],
    ['updateDailyNutrition (stale)', { action: 'updateDailyNutrition', sessionId: 'NF-310001', entryId: logRow[25], expectedLastModified: 'stale', entry: ORDER('draft') }],
    ['publishLog', { action: 'publishLog', sessionId: 'NF-310001', entryId: logRow[25], expectedLastModified: logRow[26] }],
    ['publishLog (stale)', { action: 'publishLog', sessionId: 'NF-310001', entryId: logRow[25], expectedLastModified: 'stale' }],
    ['updatePatient', { action: 'updatePatient', patient: Object.assign({}, n1, { diagnosis: 'X' }), base: n1 }],
    ['registerPatient over the record', { action: 'registerPatient', patient: Object.assign({}, n1, { diagnosis: 'X' }) }],
    ['updateWeights', { action: 'updateWeights', sessionId: 'NF-310001', weights: [{ dol: 1, w: 1500 }, { dol: 5, w: 1550 }] }],
    ['deletePatient', { action: 'deletePatient', sessionId: 'NF-310001', confirmPublished: true }],
    ['logNursingEntry', { action: 'logNursingEntry', sessionId: 'NF-310001', entry: { ts: TODAY, ivInMl: 100 } }],
    ['acquireLogLock', { action: 'acquireLogLock', sessionId: 'NF-310001', date: TODAY }],
    ['releaseLogLock', { action: 'releaseLogLock', sessionId: 'NF-310001', date: TODAY }],
  ];
}

T.section('§6 writes and the order lock, outside the caller\'s wards', () => withNow(NOON, () => {
  const g = ward({ nursing: true });
  // The NICU doctor holds the order lock, so a lock reply that named its holder would show.
  const held = g.as('nicuDoc', { action: 'acquireLogLock', sessionId: 'NF-310001', date: TODAY });
  T.ok('6.0 the NICU doctor takes the order lock', held.ok === true && held.locked === false, held);
  for (const [name, body] of writes(g)) {
    const before = sheetsNow(g);
    const lockBefore = g.cacheStore.get('loglock_NF-310001_' + TODAY);
    const auditBefore = g.audit().length;
    const text = g.asText('pedDoc', body);
    const r = JSON.parse(text);
    T.ok(`6.${name} · refused`, !!r.error && r.ok !== true && r.conflict !== true && r.needsConfirm !== true, r);
    T.ok(`6.${name} · no sheet changed`, sheetsNow(g) === before);
    T.ok(`6.${name} · the lock is as it was`, JSON.stringify(g.cacheStore.get('loglock_NF-310001_' + TODAY)) === JSON.stringify(lockBefore));
    T.eq(`6.${name} · the reply names no one`, [leaks(text, ['NF-310001']), /Staff nicuDoc|nicu\.doc@/.test(text)], [[], false]);
    const rows = g.audit().slice(auditBefore);
    T.ok(`6.${name} · audited, with no patient identifier`,
      rows.some(a => /^wardScopeRefused/.test(a.action) && a.sessionId === '' && a.actor === ACCOUNTS.pedDoc.email)
      && rows.every(a => !String(a.action).includes('NF-310001') && a.sessionId === ''), rows);
  }
  // The same writes by an account with no ward.
  for (const [name, body] of writes(g).slice(0, 3)) {
    const before = sheetsNow(g);
    const r = g.as('noWard', body);
    T.ok(`6.${name} by an account with no ward · refused, nothing changed`, !!r.error && r.ok !== true && sheetsNow(g) === before, r);
  }
  const own = g.as('nicuDoc', { action: 'logDailyNutrition', sessionId: 'NF-310001', entry: ORDER('submitted') });
  T.ok('6.20 the NICU doctor still saves the NICU infant\'s order', !!own.entryId, own);
  const pedOwn = g.as('pedDoc', { action: 'logDailyNutrition', sessionId: 'NF-310003', entry: ORDER('submitted') });
  T.ok('6.21 the PED doctor saves the PED child\'s order', !!pedOwn.entryId, pedOwn);
  const nurse = g.as('pedNurse', { action: 'logNursingEntry', sessionId: 'NF-310003', entry: { ts: TODAY, ivInMl: 80 } });
  T.ok('6.22 the PED nurse records the PED child\'s I/O', nurse.ok === true, nurse);
  const admin = g.as('admin', { action: 'updateWeights', sessionId: 'NF-310006', weights: [{ dol: 1, w: 1500 }, { dol: 4, w: 1520 }] });
  T.ok('6.23 an admin writes to an infant in no ward', admin.ok === true, admin);
  const newOut = g.as('pedDoc', { action: 'registerPatient', isNew: true, patient: reg('NF-330001', 'NICU 8') });
  T.ok('6.24 a PED doctor registering a child into a NICU bed is refused', !!newOut.error && newOut.ok !== true, newOut);
  const newNone = g.as('pedDoc', { action: 'registerPatient', isNew: true, patient: reg('NF-330002', '') });
  T.ok('6.25 …and into no bed (a record only an admin would see)', !!newNone.error && newNone.ok !== true, newNone);
  T.ok('6.26 …and nothing was registered', !g.rows('Patient_Registry').some(r => /^NF-33/.test(r[0])));
  const newIn = g.as('pedDoc', { action: 'registerPatient', isNew: true, patient: reg('NF-330003', 'PED 4') });
  T.ok('6.27 a PED doctor registers a child into PED 4', newIn.ok === true, newIn);
  T.ok('6.28 …who is on the PED doctor\'s next sync', sids(sync(g, 'pedDoc')).includes('NF-330003'));
}));

T.section('§7 a parked child, a bed in no ward, no bed', () => withNow(NOON, () => {
  const g = ward();
  T.ok('7.1 the parked PED child reaches the PED nurse and no NICU or SCN account',
    sids(sync(g, 'pedNurse')).includes('NF-310004') && !sids(sync(g, 'nicuNurse')).includes('NF-310004') && !sids(sync(g, 'nicuDoc')).includes('NF-310004'));
  const w = g.as('pedNurse', { action: 'updateWeights', sessionId: 'NF-310004', weights: [{ dol: 1, w: 1500 }, { dol: 6, w: 1510 }] });
  T.ok('7.2 the PED nurse records the parked child\'s weight', w.ok === true, w);
  const p4 = asSynced(g, 'pedNurse', 'NF-310004');
  const bedded = g.as('pedNurse', { action: 'updatePatient', patient: Object.assign({}, p4, { currentBed: 'PED 3' }), base: p4 });
  T.ok('7.3 …and gives the child a PED bed', bedded.ok === true, bedded);
  T.ok('7.4 the parked NICU infant stays with NICU', sids(sync(g, 'nicuDoc')).includes('NF-310005') && !sids(sync(g, 'pedDoc')).includes('NF-310005'));
  T.ok('7.5 a bed in no ward (OR 1), and no bed at all: an admin only',
    ['nicuDoc', 'nicuNurse', 'pedDoc', 'pedNurse', 'noWard'].every(who => !sids(sync(g, who)).some(s => s === 'NF-310006' || s === 'NF-310007'))
    && ['NF-310006', 'NF-310007'].every(s => sids(sync(g, 'admin')).includes(s)));
  const r = g.as('nicuDoc', { action: 'updateWeights', sessionId: 'NF-310006', weights: [{ dol: 1, w: 1500 }, { dol: 3, w: 1490 }] });
  T.ok('7.6 a NICU doctor cannot write to the infant in no ward', !!r.error && r.ok !== true, r);
}));

T.section('§8 a registry read that fails', () => withNow(NOON, () => {
  const g = ward();
  const reg8 = g.sheet('Patient_Registry');
  const before = sheetsNow(g);
  reg8.hooks.beforeRead = () => { throw new Error('Service Spreadsheets timed out while accessing document with id x.'); };
  const r = g.as('nicuDoc', { action: 'logDailyNutrition', sessionId: 'NF-310001', entry: ORDER('draft') });
  const lock = g.as('pedDoc', { action: 'acquireLogLock', sessionId: 'NF-310001', date: TODAY });
  reg8.hooks.beforeRead = null;
  T.ok('8.1 an order save whose ward cannot be read is refused, not let through', !!r.error && r.ok !== true && !r.entryId, r);
  T.ok('8.2 …nothing changed', sheetsNow(g) === before);
  T.ok('8.3 the order lock too', !!lock.error && lock.ok !== true, lock);
}));

T.section('§9 the TPN room still sees every ward\'s orders', () => withNow(NOON, () => {
  const g = ward({ noLog: true });
  g.as('nicuDoc', { action: 'logDailyNutrition', sessionId: 'NF-310001', entry: ORDER('submitted') });
  g.as('pedDoc', { action: 'logDailyNutrition', sessionId: 'NF-310003', entry: ORDER('submitted') });
  const rx = g.as('rx', { action: 'pharmacyOrders', date: TODAY });
  T.eq('9.1 both orders, each with its bed', (rx.orders || []).map(o => [o.sessionId, o.bed]).sort(), [['NF-310001', 'NICU 3'], ['NF-310003', 'PED 2']]);
  T.eq('9.2 …with no name, initials or date of birth', leaks(JSON.stringify(rx).replace(/NF-31000[13]/g, ''), ['NF-310001', 'NF-310003']), []);
  T.eq('9.3 pharmacy still reads no registry', g.as('rx', { action: 'getActivePatients' }).error, 'Forbidden');
}));

T.section('§10 setting an account\'s wards', () => withNow(NOON, () => {
  const g = ward();
  const staffBefore = JSON.stringify(g.sheet('Staff').data);
  for (const who of ['nicuDoc', 'nicuNurse', 'pedDoc', 'noWard']) {
    const r = g.as(who, { action: 'setStaffWards', email: ACCOUNTS.noWard.email, wards: ['NICU'] });
    T.ok(`10.1 a ${ACCOUNTS[who].role} (${who}) is refused`, r.error === 'Forbidden', r);
  }
  T.ok('10.2 Staff did not change', JSON.stringify(g.sheet('Staff').data) === staffBefore);
  T.eq('10.3 only an admin lists the accounts\' wards', ['nicuDoc', 'rx'].map(w => g.as(w, { action: 'getStaffWards' }).error), ['Forbidden', 'Forbidden']);
  const list = g.as('admin', { action: 'getStaffWards' });
  T.ok('10.4 an admin lists every account with its role, name and wards', list.ok === true && Array.isArray(list.staff) && list.staff.length === Object.keys(ACCOUNTS).length, list);
  const row = (list.staff || []).find(s => s.email === ACCOUNTS.pedNurse.email) || {};
  T.eq('10.5 …the PED nurse holds PED', [row.role, row.wards], ['nurse', ['PED']]);
  T.ok('10.6 …and no password hash, salt or temp password', !/password_hash|salt|temp/i.test(Object.keys(row).join(' ')) && !JSON.stringify(list).includes(g.sheet('Staff').data[1][4]));
  T.eq('10.7 …with the ward table to choose from', (list.wardTable || []).map(w => w.key), ['NICU', 'SCN', 'PED']);
  const set = g.as('admin', { action: 'setStaffWards', email: ACCOUNTS.noWard.email, wards: ['SCN', 'NICU'] });
  T.ok('10.8 an admin gives the new account NICU and SCN', set.ok === true, set);
  T.eq('10.9 …the cell holds them in table order', g.sheet('Staff').data.find(r => r[0] === ACCOUNTS.noWard.email)[8], 'NICU,SCN');
  T.eq('10.10 …the account\'s very next sync has NICU and SCN infants', sids(sync(g, 'noWard')), [...idsOf('NICU'), ...idsOf('SCN')].sort());
  const au = g.audit().filter(a => /^setStaffWards/.test(a.action));
  T.ok('10.11 …audited: who, whose account, which wards, and no patient', au.length === 1 && au[0].actor === ACCOUNTS.admin.email
    && JSON.stringify(au[0]).includes(ACCOUNTS.noWard.email) && /NICU,SCN/.test(JSON.stringify(au[0])), au);
  const off = g.as('admin', { action: 'setStaffWards', email: ACCOUNTS.noWard.email, wards: [] });
  T.ok('10.12 an admin takes every ward away', off.ok === true && sids(sync(g, 'noWard')).length === 0, off);
  const bad = [
    ['a key not in the table', { email: ACCOUNTS.pedNurse.email, wards: ['ICU'] }],
    ['"*"', { email: ACCOUNTS.pedNurse.email, wards: ['*'] }],
    ['a key twice', { email: ACCOUNTS.pedNurse.email, wards: ['PED', 'PED'] }],
    ['not a list', { email: ACCOUNTS.pedNurse.email, wards: 'PED' }],
    ['an account that does not exist', { email: 'nobody@kcmh.test', wards: ['PED'] }],
    ['an admin account (every ward by role)', { email: ACCOUNTS.admin.email, wards: ['PED'] }],
    ['a pharmacy account (no ward by role)', { email: ACCOUNTS.rx.email, wards: ['PED'] }],
  ];
  for (const [name, b] of bad) {
    const before = JSON.stringify(g.sheet('Staff').data);
    const r = g.as('admin', Object.assign({ action: 'setStaffWards' }, b));
    T.ok(`10.13 refused: ${name}`, !!r.error && r.ok !== true && JSON.stringify(g.sheet('Staff').data) === before, r);
  }
  T.ok('10.14 a pharmacy account is refused setStaffWards', g.as('rx', { action: 'setStaffWards', email: ACCOUNTS.noWard.email, wards: ['NICU'] }).error === 'Forbidden');
}));

T.section('§11 the migration', () => withNow(NOON, () => {
  // A Staff tab as the live one is today: eight columns, no wards. Every infant on a NICU or SCN bed,
  // or parked from one, except one with no bed at all, which the migration lists.
  const g = boot({ src: SRC });
  const staff = g.sheet('Staff');
  staff.data.splice(0, staff.data.length, ['email', 'role', 'name', 'active', 'password_hash', 'salt', 'must_change_password', 'temp_password']);
  const old = [['a@kcmh.test', 'admin'], ['d1@kcmh.test', 'doctor'], ['d2@kcmh.test', 'Doctor '], ['n1@kcmh.test', 'nurse'],
    ['rx2@kcmh.test', 'pharmacy'], ['off@kcmh.test', 'doctor', false]];
  for (const [e, role, active] of old) staff.data.push([e, role, e, active === undefined ? true : active, '', '', false, '']);
  const nicuOnly = INFANTS.filter(i => i.ward === 'NICU' || i.ward === 'SCN');
  for (const i of [...nicuOnly, INFANTS.find(x => x.sid === 'NF-310007')]) {
    g.seedPatient({ sessionId: i.sid, name: NAME(i.sid), bw: 1500, ga: 32.1, dob: DOB, admissionDate: DOB, status: 'Active',
      currentBed: i.bed, bedHistory: i.hops || [], weights: [{ dol: 1, w: 1500 }] });
  }
  const dry = g.sb.migrateStaffWards && g.sb.migrateStaffWards();
  T.ok('11.1 the dry run changes nothing', !!dry && dry.applied === false && staff.data[0].length === 8 && staff.data.every(r => r.length === 8), dry);
  T.eq('11.2 …and says what it would fill (four doctors and nurses, one of them disabled)', dry && dry.wouldFill, 4);
  const res = g.sb.applyStaffWardsMigration();
  T.eq('11.3 it adds the wards column by header', staff.data[0][8], 'wards');
  const cell = (e) => (staff.data.find(r => r[0] === e) || [])[8] || '';
  T.eq('11.4 every doctor and nurse holds NICU,SCN (a role cell in any case included); admin and pharmacy stay blank',
    ['a@kcmh.test', 'd1@kcmh.test', 'd2@kcmh.test', 'n1@kcmh.test', 'rx2@kcmh.test', 'off@kcmh.test'].map(cell),
    ['', 'NICU,SCN', 'NICU,SCN', 'NICU,SCN', '', 'NICU,SCN']);
  T.eq('11.5 it lists the infants on the unit with no ward, by ID', res && res.patientsWithNoWard, ['NF-310007']);
  T.ok('11.6 its log names no infant by name', !g.env.logs.join('\n').includes(NAME('NF-310007')));
  staff.data.find(r => r[0] === 'n1@kcmh.test')[8] = 'SCN';
  const again = g.sb.applyStaffWardsMigration();
  T.eq('11.7 run again: it fills nothing and leaves a ward an admin set', [again && again.filled, cell('n1@kcmh.test'), staff.data[0].length], [0, 'SCN', 9]);
  staff.data.find(r => r[0] === 'n1@kcmh.test')[8] = 'NICU,SCN';
  // Before and after: what a doctor saw before ward scope is every infant in the sync window; now it is
  // the same set, less the one with no bed, which the migration listed for an admin to give a bed.
  g.addStaff('d3@kcmh.test', 'doctor', PWD, { wards: 'NICU,SCN' });
  const tok = g.session('d3@kcmh.test', 'doctor');
  const after = sids(g.post({ token: tok, action: 'getActivePatients' }));
  const all = sids(g.post({ token: g.session('a@kcmh.test', 'admin'), action: 'getActivePatients' }));
  T.eq('11.8 a migrated doctor sees every infant an admin sees, less the one the migration listed', after, all.filter(s => s !== 'NF-310007'));
}));

T.done();
